from math import dist


def get_medoid(cluster):
    return min(cluster, key=lambda p: sum(dist(p, q) for q in cluster))


def dbscan(data, eps=2):
    clusters = []

    while data:
        point = data.pop()
        cluster = [point]
        queue = [point]

        while queue:
            current = queue.pop(0)
            neighbors = [p for p in data if dist(current, p) < eps] cluster.extend(neighbors) queue.extend(neighbors) data[:] = [p for p in data if p not in neighbors] clusters.append(cluster) return clusters # == файл А == # with open('2716_A.txt') as file: next(file) data_A = [list(map(float, i.split())) for i in file] clusters_A = dbscan(data_A) medoids_A = [get_medoid(cluster) for cluster in clusters_A] px = sum(x for x, y in medoids_A) py = sum(y for x, y in medoids_A) print(abs(int(px * 10_000)), abs(int(py * 10_000))) # == файл B == # with open('2716_B.txt') as file: next(file) data_B = [list(map(float, i.split())) for i in file] clusters_B = dbscan(data_B) clusters_B = [cluster for cluster in clusters_B if len(cluster) > 2]

medoids_B = [get_medoid(cluster) for cluster in clusters_B]

q1 = min(dist(medoid, (0, 0)) for medoid in medoids_B)
q2 = max(dist(medoid, (0, 0)) for medoid in medoids_B)

print(abs(int(q1 * 10_000)), abs(int(q2 * 10_000)))
